import{_ as a,o as t,c as i,a2 as n}from"./chunks/framework.BGlkWkwp.js";const d=JSON.parse('{"title":"A list with actions","description":"","frontmatter":{},"headers":[],"relativePath":"patterns/list.md","filePath":"patterns/list.md"}'),o={name:"patterns/list.md"};function s(r,e,l,h,c,p){return t(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="a-list-with-actions" tabindex="-1">A list with actions <a class="header-anchor" href="#a-list-with-actions" aria-label="Permalink to &quot;A list with actions&quot;">​</a></h1><p>A list of things that can be found, selected and acted on, one at a time or together, with pages when there are many.</p><h2 id="when-to-use" tabindex="-1">When to use <a class="header-anchor" href="#when-to-use" aria-label="Permalink to &quot;When to use&quot;">​</a></h2><p>Use it for the documents, the members or the files of a place. When the things have several values to compare, use a <a href="./../components/table">Table</a>; when they are a hierarchy, a <a href="./../components/tree">Tree</a> or a <a href="./../workbench/layer-tree">LayerTree</a>.</p><h2 id="parts" tabindex="-1">Parts <a class="header-anchor" href="#parts" aria-label="Permalink to &quot;Parts&quot;">​</a></h2><ul><li>A <a href="./../components/row">Row</a> above the list with a <a href="./../components/search-input">SearchInput</a> and the action that creates a new item. Filters in effect go in a <a href="./../components/filter-bar">FilterBar</a>.</li><li>A <a href="./../components/list">List</a> of <a href="./../components/list-item">ListItem</a>s: a <a href="./../components/checkbox">Checkbox</a> to select, a mark, the name, a muted caption and a <a href="./../components/kebab">Kebab</a> for the actions of one item.</li><li>A <a href="./../components/bulk">Bulk</a> bar while items are selected, with the actions on all of them and a button that clears the selection.</li><li>A <a href="./../components/pager">Pager</a> at the end of the list.</li><li>A <a href="./../components/state">State</a> in place of the list when it is empty, or when nothing matches the search, with the action that helps.</li></ul><h2 id="rules" tabindex="-1">Rules <a class="header-anchor" href="#rules" aria-label="Permalink to &quot;Rules&quot;">​</a></h2><ul><li>The name clips to one line; the full name shows on hover.</li><li>An action on one item is in its Kebab; the same action on several is in the Bulk bar. A destructive action asks before it acts.</li><li>An empty list says why it is empty and what to do, in one sentence and one action.</li></ul><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h2><figure class="kata-example"><iframe src="/kata/examples/pattern-list/" title="A list with actions" loading="lazy" style="width:100%;height:32rem;border:1px solid var(--vp-c-divider);border-radius:8px;"></iframe><figcaption><a href="/kata/examples/pattern-list/" target="_blank" rel="noopener">A list with actions</a></figcaption></figure>',10)])])}const f=a(o,[["render",s]]);export{d as __pageData,f as default};
